#!/usr/bin/env python3
from pathlib import Path
import json,csv,sys,math,statistics as st,shutil,hashlib,datetime
O=Path(sys.argv[1]).resolve();M=json.loads((O/'manifest.json').read_text());assert M.get('finished');R=list(csv.DictReader((O/'summary.csv').open()))
for r in R:
 for k in r:
  if k not in ['case','collision','mode','profile','density_hash']:r[k]=float(r[k])
def get(k,n=1,res=24,hits=0,col='mesh',mode='cpu'):
 return next((r for r in R if r['case']==k and r['count']==n and r['resolution']==res and r['hits']==hits and r['collision']==col and r['mode']==mode and r['profile']=='False'),None)
def f(v):return '—' if v is None else f'{v:.3f}'
def n(v):return str(int(v))
lines=['# Tessera destructible voxel shooter benchmark','',f'Tested commit **{M["engine_commit"]}**. Completed {M["finished"]}. Clean commit checkout, fresh Release native dependencies and engine build, Ryzen 9 7900X, RTX 3070 8 GB, Linux/Vulkan. **{len(M["jobs"])} measured processes**; all command lines, samples and checks are retained.','', '## Assessment','', '**A bounded shooter with destructible map sections, explosions and digging looks plausible on this desktop. Idle rendering is not the main obstacle. Immediate mesh/collision rebuilds, fragmentation correctness, memory, and scheduling destruction bursts are the important constraints.** This is not a whole-game or multiplayer capacity guarantee.','', 'Every VoxelObject retains a normal generated mesh between edits. Only the affected object remeshes. There is no whole-map rebuild in these tests. Each voxel object still owns a grid, its own mesh and collision data; identical voxel objects do not automatically share their meshes.','', '## Intact map pieces','', '720p, one directional light, simple vertex-coloured material, no shadows/AA; all pieces framed together. Mesh colliders are enabled. Values are the worst process p95 among three independent runs. Peak RSS is CPU process resident memory, **not total RAM+VRAM**; it includes renderer/driver allocations and setup peaks.','', '| Objects | Resolution | Unique voxel meshes p95 ms | Same-geometry shared-mesh control p95 ms | Voxel process peak RSS MiB | Shared control RSS MiB |','|---|---:|---:|---:|---:|---:|']
for res,counts in [(16,[100,500,1000]),(24,[100,500,1000]),(32,[100,500]),(48,[100])]:
 for count in counts:
  a=get('idle',count,res,mode='render');b=get('shared',count,res,mode='render')
  lines.append(f'| {count} | {res} | {f(a["worst_process_frame_p95_ms"])} | {f(b["worst_process_frame_p95_ms"] if b else None)} | {f(a["rss_mib"])} | {f(b["rss_mib"] if b else None)} |')
lines+=['','The shared-mesh control draws the **same voxel-generated geometry** at the same object count using one source mesh. It retains one VoxelObject, then shares that mesh among ordinary MeshRenderers; it is an instancing/reuse control, not a destructible replacement. All objects still have mesh colliders. RSS includes one extra int8 density backup per benchmark voxel object for reproducible edits, even in idle tests; a game without backups saves that portion. No VRAM ceiling is established.','', '1080p with shadows and antialiasing enabled:','','| Objects | Voxel p95 ms | Shared control p95 ms |','|---|---:|---:|']
for count in [100,500]:
 a=get('idle',count,24,mode='hq');b=get('shared',count,24,mode='hq');lines.append(f'| {count} | {f(a["worst_process_frame_p95_ms"])} | {f(b["worst_process_frame_p95_ms"] if b else None)} |')
lines+=['','## Bullets and digging','', '**Bullet carve radius is 0.32 m (64 cm diameter): a large visible chip, not a realistic calibre-sized bullet hole.** Resolution 24 over a 4 m object means 16.7 cm cells; resolution 48 means 8.3 cm cells. Millimetre bullet holes require decals or a different finer/local representation. Objects can instead be made physically smaller at the same resolution for finer cells.','', 'Digging tests use a 4 m grid containing a 3.2 m × 3.2 m × 0.7 m wall and a 0.5 m-radius cut through its centre. The exact mesh collider must let a ray through the new hole after every edit. Other bullet tests use a solid primitive box. Every measured iteration begins with an untimed density-only restore, then performs productive edits; no Fill or mesh/collision rebuilding is hidden in the measured edit. Reset cleanup and correctness scans are outside the narrow SAMPLE action/CPU timers. Full rendered FRAME intervals still include that benchmark housekeeping, so event-frame figures conservatively include work a production game would replace with its own event/cleanup logic.','', '| Resolution | Cell size cm (4 m grid) | Mesh generation/edit only, CPU p95 ms | With exact static collision, CPU p95 ms | With convex rigidbody, CPU p95 ms | Carving bullet: rendered p95 ms | Digging through wall: rendered p95 ms |','|---|---:|---:|---:|---:|---:|---:|']
for res in [8,16,24,32,48]:
 values=[get('shots',res=res,hits=1,col=c) for c in ['none','mesh','dynamic']];render=get('shots',res=res,hits=1,mode='render');dig=get('slab',res=res,hits=1,mode='render')
 lines.append(f'| {res} | {400/res:.2f} | '+' | '.join(f(x['worst_process_action_p95_ms'] if x else None) for x in values)+f' | {f(render["worst_process_frame_p95_ms"] if render else None)} | {f(dig["worst_process_frame_p95_ms"] if dig else None)} |')
lines+=['','Resolution-8 bullet tests changed density but failed the benchmark’s positive-solid-sample removal gate; their timings are excluded. This does not prove the engine cannot draw any small dent: it means this coarse grid did not pass this specific material-removal test. Digging at that resolution is tested separately.','', 'The CPU-only collision comparison includes edit, meshing and collider/body rebuilding but no graphics device. The difference between no collider and mesh collider is an estimate of collision integration cost, not a separately instrumented pure Jolt function. Moving convex collision cannot represent concave holes or tunnels; it is appropriate for approximate loose props/debris, not exact traversable wall openings.','', 'Bullets that do not carve are much less demanding:','','| Intact objects, resolution 24 | 1,000 ray queries: CPU total p95 ms |','|---|---:|']
for count in [100,500,1000]:
 a=get('rays',count,24);lines.append(f'| {count} | {f(a["total_p95_ms"])} |')
lines+=['','All 1,000 ray queries must hit. This is a synthetic query batch, not 1,000 fully simulated projectiles or networked shots.','', '## Explosions affecting multiple objects','', 'Synthetic fan-out: each affected 4 m-grid box receives its own 1 m-radius carve at a fixed local point. This models the cost of touching N objects, not the geometry of a single 1 m world-space explosion spanning widely separated boxes. Real blast overlap, full object removal and fragmentation can change cost. No fragments are detached in this fan-out case; fragmentation is measured separately.','', '| Resolution | Affected objects | Rendered median ms | Worst-process rendered p95 ms |','|---|---:|---:|---:|']
for res in [16,24,32]:
 for count in [1,4,16]:
  a=get('blast',count,res,count,mode='render');lines.append(f'| {res} | {count} | {f(a["frame_median_ms"])} | {f(a["worst_process_frame_p95_ms"])} |')
lines+=['','A 60 FPS frame is 16.67 ms; a 120 FPS frame is 8.33 ms. These destruction costs must fit alongside the rest of the game. They are not whole-game FPS predictions. Event-frame intervals also include the repeat/reset and validation overhead described above; narrow action columns isolate the edit service time.','', '## Dirty-object queue and coalescing','', '**Coalescing is measured here in a benchmark-only prototype; it is not enabled in the engine.** It applies the same density edits, then calls the current Rebuild once per dirty object, including exact collision rebuilding. It has no threads, asynchronous collision cooking or compute shader. The prototype omits fragment splitting and networking. Final density FNV hashes, vertex counts and triangle counts must match immediate editing for every paired case.','', '| Resolution | Edits to one object | Immediate rendered p95 ms | One rebuild rendered p95 ms | Speedup (frame medians) |','|---|---:|---:|---:|---:|']
for res in [16,24,32]:
 for hits in [4,16]:
  a=get('burst',res=res,hits=hits,mode='render');b=get('batch',res=res,hits=hits,mode='render');lines.append(f'| {res} | {hits} | {f(a["worst_process_frame_p95_ms"])} | {f(b["worst_process_frame_p95_ms"])} | {a["frame_median_ms"]/b["frame_median_ms"]:.2f}× |')
lines+=['','A queue should deduplicate dirty objects, combine same-object hits, prioritize nearby gameplay-relevant changes, and use a time budget rather than a fixed object count. CPU meshing can be prepared on workers; GPU uploads and physics swaps need safe ownership/commit points. Density changes that happen while a worker is meshing need versioning so completed work does not overwrite newer edits.','', 'A simple queue-drain estimate below uses the **worst process p95 single-object CPU action time** measured for a blast, then assumes whole jobs must fit in the budget. It is arithmetic, not an implemented queue benchmark. It excludes other game work, collision-commit synchronization, async latency and scheduling overhead. An object taking longer than the budget cannot be made cheap merely by putting it in a queue; it needs smaller pieces, finer-grained jobs or background work.','', '| Resolution | Single-object service estimate ms | Budget ms/frame | Objects/frame | Frames to finish 16 objects | Delay at 60 FPS ms |','|---|---:|---:|---:|---:|---:|']
for res in [16,24,32]:
 t=get('blast',1,res,1)['worst_process_action_p95_ms'] if get('blast',1,res,1) else get('blast',1,res,1,mode='render')['worst_process_action_p95_ms']
 for budget in [2,4,8]:
  rate=int(budget//t)
  if rate:frames=math.ceil(16/rate);lines.append(f'| {res} | {f(t)} | {budget} | {rate} | {frames} | {frames*1000/60:.1f} |')
  else:lines.append(f'| {res} | {f(t)} | {budget} | job exceeds budget | — | — |')
lines+=['','Immediate impact particles, dust and decals can hide short visual delays, but a newly visible hole should not remain blocked by old collision. Voxel-density hitscan queries could respond before mesh/collider replacement; player and rigidbody collision still need an updated representation. A queue does not remove total work, and repeated demand above its service rate grows the backlog.','', '## Fragment creation and debris','', 'The split test uses two solid lobes joined by a narrow bridge. A centre cut must detach a fragment. It includes fragment allocation, remeshing, convex collision, rigidbody creation and one physics/update tick. Old fragments are removed outside the timer to repeat the same event; this does not measure permanent accumulation.','', '| Simultaneous splits, resolution 24 | Rendered p95 ms | Fragments per event |','|---|---:|---:|']
for count in [1,4,16]:
 a=get('split',count,24,count,mode='render');lines.append(f'| {count} | {f(a["worst_process_frame_p95_ms"])} | {a["spawned_fragments"]/(48):.0f} |')
lines+=['','**Correctness blocker:** the resolution-16 split test fails grid-layout validation. SpawnPiece creates a new default-resolution component, then changes resolution without resizing its sample arrays/counter before copying the parent grid. The observed fragment retains the default 25³ samples instead of 17³. Above default resolution, the source also copies a larger parent grid into default-sized fragment arrays, so those fragmentation cases were deliberately not executed. Fix and regression-test fragment allocation before using mixed resolutions for destructible map pieces. Timings for the rejected split are excluded.','', 'Existing detached pieces retain the full parent-sized voxel grid, even when the fragment is tiny. Their collision is a convex hull, not an exact concave surface. The following debris stress uses already-created separate voxel boxes with convex rigidbodies on a floor; they are gently kept active. It isolates ongoing debris cost, not fragment spawning or a dense rubble pile.','', '| Active debris objects | Resolution | Worst-process rendered p95 ms | Peak process RSS MiB |','|---|---:|---:|---:|']
for res in [8,16,24]:
 for count in [100,500]:
  a=get('debris',count,res,col='dynamic',mode='render');lines.append(f'| {count} | {res} | {f(a["worst_process_frame_p95_ms"])} | {f(a["rss_mib"])} |')
lines+=['','A production game should cap active fragments, remove/merge small debris, and consider converting distant settled rubble to ordinary meshes. Every retained fragment being recursively destructible costs more memory than visual rubble alone. Dense piles, chains of explosions and full structure collapse need additional tests.','', '## Imported model startup','', 'Setup includes voxelization and initial collision; subsequent idle CPU ticks are not voxelizing the model repeatedly. These are simple built-in closed cube/sphere meshes, not production assets with thousands of triangles. Model voxelization scans samples against source triangles and can be much more expensive for detailed assets. Precompute/cache voxel data for shipped maps rather than voxelizing a whole level during action.','', '| Source | Resolution | Setup median ms |','|---|---:|---:|']
for kind in ['model-cube','model-sphere']:
 for res in [16,24,32]:a=get(kind,res=res);lines.append(f'| {kind} | {res} | {f(a["setup_ms"])} |')
lines+=['','## Compute shaders','', 'GPU meshing was **not benchmarked or implemented**. It could accelerate density processing/visual marching cubes, but current Jolt collision still needs CPU-accessible geometry and CPU shape preparation. A GPU collision-mesh generator would therefore still require asynchronous readback and physics integration. Separate coarse collision meshes may help, provided gameplay holes remain representable. The no-collider versus static-collider rows show why speeding up visual meshing alone cannot eliminate the entire update cost. Start by coalescing edits and profiling mesh/collision stages; evaluate compute against that improved CPU baseline.','', '## Suggested shooter design','', '- Use VoxelObjects for independently destructible wall sections, terrain-like blocks and props; leave weapons, characters and tiny cosmetic items as ordinary meshes unless they genuinely need volumetric destruction.','- Begin with resolution 16–24 for ordinary map sections; use small physical chunks for required detail rather than setting every large model to 48. Keep sections closed and avoid very long, thin models that waste a cubic grid.','- Ordinary bullets can use hitscan and decals. Reserve volumetric carving for explosions, digging and selected weapons; if carving every bullet, batch same-object edits before rebuilding.','- Add a deduplicated, versioned update queue with a small measured frame budget, and separate visible/hitscan responsiveness from safe physics-shape commits. Profile its queue age under sustained combat, not only average FPS.','- Fix the nondefault-resolution fragment allocation issue, bound active debris and memory, and test real map geometry with multiple simultaneous explosions before committing to a whole-map destruction design.','- Multiplayer carve event routing and shared fragment identities exist, but these tests are single-process with no network session. Bandwidth, authoritative validation, late-join world state, replication of queue delays and desync resistance are not established. Navigation updates after destruction are not included.','', '## Full measured inventory','', 'Statistics are medians across processes except the explicitly named worst-process p95. Each event case uses 8 warmup and 40 samples × 3 processes unless its command specifies otherwise; idle/render tests use 40/100, rays 20/80, debris 60/120, model setup 2/10. Separate instrumented profiler runs use one process and do not contribute to practical comparison tables.','', '| Case | N | Res | Edits | Collision | Mode | Action median ms | Action p95 ms | Physics median ms | CPU total p95 ms | Worst-process frame p95 ms | Setup ms | RSS MiB |','|---|---:|---:|---:|---|---|---:|---:|---:|---:|---:|---:|---:|']
for r in R:
 if r['profile']!='False':continue
 lines.append('| '+' | '.join([r['case'],n(r['count']),n(r['resolution']),n(r['hits']),r['collision'],r['mode'],f(r['action_median_ms']),f(r['action_p95_ms']),f(r['physics_median_ms']),f(r['total_p95_ms']),f(r['worst_process_frame_p95_ms']) if r['mode']!='cpu' else '—',f(r['setup_ms']),f(r['rss_mib'])])+' |')
bad=[j for j in M['jobs'] if not j['valid']]
lines+=['','## Reproducibility and validation','',f'- {len(M["jobs"])} measurement processes: {len(M["jobs"])-len(bad)} pass fixture validation; {len(bad)} rejected. Rejections are four coarse-grid bullet cases and one nondefault fragment-layout case, not accepted performance wins.','- Accepted runs must return success, emit complete finite timings, report finite final mesh positions, and have no solver-capacity error. Every edit must report success and remove positive solid samples; fragment tests must actually create pieces with the correct grid layout. Digging must open collision to a ray. Ray batches must all hit. Rendered runs must emit all frame intervals and nonzero draw calls.','- All geometry is local to a isolated checkout of the recorded commit and freshly built native dependencies. No engine implementation changes were made. The coalescing prototype lives only in the benchmark harness. The engine commit and its source files were not modified. Native archive was built with the current Release configuration; Beef Release uses GNU linking with ThinLTO unavailable.','- Timed edit/action includes CarveLocal or the prototype, full mesh creation, collision rebuilding and uploads on rendered runs. CPU total also includes one 60 Hz Scene.FixedUpdate and one Scene.Update. Full-frame intervals include rendering/presentation. At overload this harness does not accumulate real-time catch-up ticks; it measures service cost, not sustained whole-game FPS.','- Density restoration, fragment cleanup needed to repeat an identical event and correctness scans are outside SAMPLE action/CPU timings but are included in inter-frame FRAME timings. Final aggregate checks are after the measurement loop. A real game still pays for its own cleanup and event routing. Extremely complex accumulated damage, dense debris piles, production material interiors, many lights, network traffic and player simulation are not covered. The floor and test colliders are physics-only; real environment drawing adds work.','- Resolution is cells along the grid’s longest side, clamped to 8–48. Primitive test grids are 4 m across, with the engine’s normal empty margin; cubes are therefore smaller than the grid. A slab is a custom thin density field. Spawned pieces keep the same parent grid.','- Peak RSS includes temporary/driver/benchmark allocations and is not a memory allocator breakdown or VRAM measurement. Processes run sequentially, unpinned, on an ordinary desktop; clocks and background load are uncontrolled. Small run-to-run differences are not guarantees.','',f'- [Per-group CSV](summary.csv), [per-process CSV](processes.csv), [commands and checks](manifest.json), [source hashes](source-sha256.json), [benchmark source](../../voxel/src/Program.bf), [runner](../../voxel/run.py).','- All raw phase samples, frame intervals, profiler recordings and build logs are packaged in [raw-data.tar.gz](raw-data.tar.gz); its file list and SHA-256 are in [artifact-integrity.json](artifact-integrity.json).','']
if (O/'voxel-capacity.png').exists():lines+=['## Charts','',f'![Voxel rendering, destruction, coalescing and memory](voxel-capacity.png)','',f'[Export SVG](voxel-capacity.svg).','']
lines += [f'[Validation audit](validation.json), [environment](environment.json), [wall-hole visual check](slab.png).','']
(O/'REPORT.md').write_text('\n'.join(lines));print(O/'REPORT.md')
